import json
from common import ROOT, save
base=ROOT/'E3';primary=json.loads((base/'executions/primary/results.json').read_text());replay=json.loads((base/'executions/replay/results.json').read_text());matrix=[];comparisons=[]
original=json.loads((base/'executions/primary/original/outputs/gray127-decoded.json').read_text())
for row in primary:
    name=row['variant'];o=row['observed'];again=next(x for x in replay if x['variant']==name)
    row['replay_record']=again
    row['replay_same_observation']=o==again['observed']
    record={'variant':name,'consumer':'Task Library 0.4.4 Python/C++ on Linux','structural_baseline_S':row['structural_status'],'generation':'NOT_APPLICABLE','compile':'PREBUILT_WHEEL','package':'PREBUILT_WHEEL',
      'load_or_initialize':o.get('initialization_status'),'inference':o.get('inference_status'),'decoder':o.get('decoder_status'),'earliest_failure':o.get('earliest_failing_stage'),'diagnostic':o.get('exception_message'),'evidence_status':'fresh E3 execution'}
    matrix.append(record)
    exp='E2' if name=='label_permutation' else 'E1'
    android=next(x for x in json.loads((ROOT/exp/'results.json').read_text())['units'] if x['variant']==name)
    matrix.append({'variant':name,'consumer':'Support 0.4.4 generated Java / Android API 30 / TFLite 2.13.0','structural_baseline_S':android['structural_status'],'generation':android['generation_status'],'compile':android['compile_status'],'package':android['package_status'],'load_or_initialize':android['load_status'],'inference':android['inference_status'],'decoder':android['decoder_status'],'earliest_failure':android.get('earliest_failing_stage'),'diagnostic':android.get('exception_message'),'evidence_status':f'reused sealed {exp} execution'})
    comparison={'variant':name,'inputs':[]}
    for case in ['gray127','rgb_pattern']:
        p=base/'executions/primary'/name/'outputs'/(case+'-decoded.json')
        if not p.exists():continue
        cats=json.loads(p.read_text())[0]['categories'];orig=json.loads((base/'executions/primary/original/outputs'/(case+'-decoded.json')).read_text())[0]['categories']
        a={c['index']:c for c in cats};b={c['index']:c for c in orig}
        comparison['inputs'].append({'input':case,'returned_index_set_equal':set(a)==set(b),'returned_score_bits_equal':all(a[i]['score_float_bits']==b[i]['score_float_bits'] for i in b),'changed_label_indices':[i for i in b if a[i]['label']!=b[i]['label']],
          'cyclic_mapping':all(a[i]['label']==b[(i+1)%1000]['label'] for i in b),
          'replay_decoded_equal':json.loads((base/'executions/replay'/name/'outputs'/(case+'-decoded.json')).read_text())==json.loads(p.read_text())})
    comparisons.append(comparison)
save(base/'results.json',{'experiment_id':'E3','units':primary,'stage_matrix':matrix,'comparisons':comparisons,'omitted_frontend':{'name':'Android Studio / Gradle ML Model Binding','status':'NOT_EVALUATED','reason':'No prepared pinned IDE/ML Model Binding configuration; optional frontend omitted from bounded comparison. No unsupported-artifact inference.'}})
lines=['# E3 results','', 'The official Task classifier rejects the deletion during initialization. The generated Android interface reaches its getter before rejecting the same model bytes. The permutation succeeds in both configurations with changed label associations.','', '| Variant | Configured consumer | S baseline | Generate | Compile/package | Initialize | Inference | Decode | Earliest failure |','|---|---|---|---|---|---|---|---|---|']
for r in matrix:lines.append(f"| {r['variant']} | {r['consumer']} | {r['structural_baseline_S']} | {r['generation']} | {r['compile']}/{r['package']} | {r['load_or_initialize']} | {r['inference']} | {r['decoder']} | {r['earliest_failure'] or '—'} |")
lines+=['','Exact Task initialization diagnostic: `ValueError: Got 1000 class(es) for output index 0, expected 999 according to the label map.` Inference and decoding were not reached for that unit. The Android diagnostic remains `IllegalArgumentException: Label number 999 mismatch the shape on axis 1` at the actual generated getter.','', 'Original, description and permutation Task paths returned all 1000 categories on both inputs. Per-index score bits agree with the Task original; the permutation changes 999 label strings. Primary and same-environment Task replay agree. Returned Task category scores are not raw interpreter tensors. No cross-platform raw-tensor equality is claimed.','', '## Implementation and compatibility evidence','', 'Official v0.4.4 image_classifier.h documents RGB batch-one UINT8/FLOAT32 inputs, required float normalization metadata, and [1,N] or [1,1,1,N] output heads. Exact original inspection satisfies these requirements (compatibility.json). The archived native binary is identified by SHA-256 in implementation.json; its separate embedded interpreter version is not established and is not assumed to equal Android 2.13.0.','', 'The Python binding calls the C++ ImageClassifier::CreateFromOptions (_pywrap_image_classifier.cc). The matching release implementation calls CheckAndSetOutputs during Init, including label-map cardinality validation (image_classifier.cc). This is not the Java TensorLabel implementation. Both share TensorFlow Lite foundations and metadata schemas; the command-line generator and its Android wrapper are one generation path, not two independent implementations. The additional classification_postprocessor.cc source is related but is not asserted to be this Python binding’s called implementation.','', '## Boundaries and deviations','', 'Android entries reuse sealed E1/E2 records; Task entries are fresh Linux executions. Platform and consumer both differ, so this is a comparison of these configured paths, not a controlled platform-effect study. The optional Android Studio / Gradle binding frontend was not evaluated; no universal support claim follows. Source discovery retained a 404 for an initial classification_head.cc candidate. API inspection corrected the planned factory spelling to create_from_array before any Task execution. No model was adapted after a failure.','', 'No independent class-order semantic reference is supplied by a second consumer reading the same labels. Structural acceptance, initialization requirements, decoder compatibility and semantic correctness remain separate.','']
(ROOT/'EXPERIMENT_E3_RESULTS.md').write_text('\n'.join(lines))
print(json.dumps(matrix,indent=2))
